<script setup lang="ts">
import { computed } from 'vue'
import { AppWindow,Building2,Users,ShieldCheck,RefreshCw,Plus,ArrowUpRight,ArrowRight,KeyRound,LockKeyhole,ChevronRight,Activity,Layers } from 'lucide-vue-next'
import { useHub } from '../store'
import AppIcon from '../components/AppIcon.vue'
const hub=useHub()
const stats=computed(()=>[{label:'接入软件',value:hub.overview.applications,unit:'个',icon:AppWindow,tone:'teal',detail:'统一 API 接入'},{label:'组织部门',value:hub.overview.departments,unit:'个',icon:Building2,tone:'blue',detail:'独立权限隔离域'},{label:'平台用户',value:hub.overview.users,unit:'人',icon:Users,tone:'violet',detail:'跨部门角色分配'},{label:'有效上下文',value:hub.overview.activeContexts,unit:'个',icon:ShieldCheck,tone:'amber',detail:'当前有效权限会话'}])
const maxMembers=computed(()=>Math.max(...hub.roles.map(r=>r.memberCount),1))
const actions:Record<string,string>={APPLICATION_CREATED:'接入新软件',ROLE_SAVED:'更新角色',ROLE_PERMISSIONS_UPDATED:'调整角色权限',USER_ROLES_UPDATED:'分配用户角色',USER_SAVED:'维护用户',CONTEXT_ISSUED:'创建权限上下文',PERMISSION_SAVED:'维护权限',API_KEY_ROTATED:'更新接口密钥',DEPARTMENT_SAVED:'维护部门',RECORD_DELETED:'删除记录',RECORD_DISABLED:'停用记录',RECORD_ENABLED:'启用记录'}
function time(s:string){return new Date(s).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false})}
</script>
<template>
  <div class="page-heading"><div><div class="eyebrow">WORKSPACE OVERVIEW</div><h1>权限概览<span class="heading-dot"></span></h1><p>{{hub.department?.name||'暂无部门'}} / {{hub.application?.name||'暂无软件'}}</p></div><div class="heading-actions"><button class="button" :disabled="hub.busy" @click="hub.load().catch(()=>{})"><RefreshCw :size="15" :class="{spin:hub.busy}" />刷新</button><RouterLink to="/applications?create=1" class="button primary"><Plus :size="16" />接入软件</RouterLink></div></div>
  <div class="stats-grid"><div v-for="stat in stats" :key="stat.label" class="stat-card"><div class="stat-top"><span>{{stat.label}}</span><span class="stat-icon" :class="stat.tone"><component :is="stat.icon" :size="20" /></span></div><div class="stat-value">{{stat.value}}<span>{{stat.unit}}</span></div><div class="stat-detail">{{stat.detail}}<ArrowUpRight :size="13" /></div></div></div>
  <section class="domain-band"><div class="domain-band-title"><span class="domain-emblem"><Layers :size="22" /></span><div><div class="domain-caption">当前权限隔离域</div><h2>{{hub.department?.name||'未选择部门'}}<span>/</span>{{hub.application?.name||'未选择软件'}}</h2></div><span class="badge green outlined"><LockKeyhole :size="11" />独立授权</span></div><div class="domain-metrics"><div><span>角色</span><strong>{{hub.overview.roles}}</strong></div><div><span>权限</span><strong>{{hub.overview.permissions}}</strong></div><div><span>已授权用户</span><strong>{{hub.overview.members}}</strong></div><RouterLink to="/roles" class="icon-button" title="管理当前域角色" aria-label="管理当前域角色"><ArrowRight :size="18" /></RouterLink></div></section>
  <div class="overview-middle">
    <section class="section-surface"><div class="section-heading"><h2>角色分布<span class="section-subtitle">当前隔离域</span></h2><RouterLink to="/roles" class="text-link">管理角色<ArrowUpRight :size="14" /></RouterLink></div><div class="distribution-meta"><span>角色名称</span><span>授权用户数</span></div><div v-if="!hub.roles.length" class="empty compact"><ShieldCheck :size="28" /><span>当前隔离域暂无角色</span><RouterLink to="/roles" class="text-link">创建角色<ArrowRight :size="14" /></RouterLink></div><div v-else class="role-distribution"><div v-for="(role,i) in hub.roles.slice(0,5)" :key="role.id" class="distribution-row"><span class="role-name"><span class="legend-dot" :class="`legend-${i%5}`"></span>{{role.name}}</span><div class="bar-track"><span :class="`bar-${i%5}`" :style="{width: `${Math.max(5,role.memberCount/maxMembers*100)}%`}"></span></div><strong>{{role.memberCount}}<span>人</span></strong></div></div><div class="surface-footer"><Users :size="14" /><span>{{hub.overview.members}} 位用户已在当前隔离域获得角色授权</span></div></section>
    <section class="section-surface model-surface"><div class="section-heading"><h2>权限关系<span class="badge neutral">RBAC0</span></h2><ShieldCheck :size="18" class="muted" /></div><div class="model-domain"><div class="model-domain-caption"><LockKeyhole :size="12" />{{hub.department?.name}} × {{hub.application?.name}}</div><div class="model-flow"><div class="model-node"><span class="model-icon blue"><Users :size="24" /></span><strong>用户</strong><small>Users</small></div><div class="model-edge"><span>分配</span><ArrowRight :size="24" /><small>多对多</small></div><div class="model-node"><span class="model-icon teal"><ShieldCheck :size="24" /></span><strong>角色</strong><small>Roles</small></div><div class="model-edge"><span>授予</span><ArrowRight :size="24" /><small>多对多</small></div><div class="model-node"><span class="model-icon amber"><KeyRound :size="24" /></span><strong>权限</strong><small>Permissions</small></div></div></div><div class="surface-footer"><span class="small-dot"></span><span>部门与软件双维度隔离</span><span class="model-footer-right">上下文实时校验</span></div></section>
  </div>
  <div class="overview-bottom">
    <section class="section-surface"><div class="section-heading"><h2>接入软件<span class="number-label">{{hub.applications.length}}</span></h2><RouterLink to="/applications" class="text-link">查看全部<ChevronRight :size="14" /></RouterLink></div><div class="table-scroll"><table class="overview-table"><thead><tr><th>软件名称</th><th>标识</th><th>状态</th><th>角色 / 权限</th><th></th></tr></thead><tbody><tr v-for="(app,i) in hub.applications.slice(0,5)" :key="app.id"><td><div class="app-cell"><AppIcon :index="i" /><strong>{{app.name}}</strong></div></td><td><code>{{app.code}}</code></td><td><span class="status-dot" :class="{disabled:!app.enabled}">{{app.enabled?'已启用':'已停用'}}</span></td><td class="tabular">{{app.roleCount}}<span class="muted"> / </span>{{app.permissionCount}}</td><td><button class="icon-button" title="切换到该软件" aria-label="切换到该软件" @click="hub.applicationId=app.id;hub.loadScope()"><ArrowUpRight :size="16" /></button></td></tr><tr v-if="!hub.applications.length"><td colspan="5" class="empty-table">暂无接入软件</td></tr></tbody></table></div><div class="surface-footer"><AppWindow :size="14" /><span>所有软件通过独立 API Key 接入</span></div></section>
    <section class="section-surface activity-surface"><div class="section-heading"><h2>最近动态</h2><RouterLink to="/audit" class="text-link">全部日志<ChevronRight :size="14" /></RouterLink></div><div class="activity-list"><div v-for="(event,i) in hub.audits.slice(0,4)" :key="event.id" class="activity-item"><div class="activity-marker" :class="{first:i===0}"><Activity :size="13" /></div><div class="activity-content"><strong>{{actions[event.action]||event.action}}</strong><span>{{event.target}}<span class="activity-actor">{{event.actor}}</span></span><time>{{time(event.createdAt)}}</time></div></div><div v-if="!hub.audits.length" class="empty compact">暂无操作记录</div></div><div class="surface-footer"><span class="small-dot"></span><span>更新于 {{hub.lastUpdated||'--'}}</span></div></section>
  </div>
</template>
